import { Book } from '@/data/books';
export function BookArt({book,large=false}:{book:Book;large?:boolean}){return <div className={'book '+(large?'large ':'')+book.tone}><div className="cover-art"><div className="sun"/><div className="hill h1"/><div className="hill h2"/><div className="tree t1"/><div className="tree t2"/><div className="child"/><div className="stars">✦　✧　✦</div></div><div className="cover-copy"><span>Little Adventures</span><h3>{book.title}</h3><em>{book.subtitle}</em></div></div>}
export function SpreadArt({art}:{art:string}){return <div className={'spread-art '+art}><div className="moon"/><div className="hill h1"/><div className="hill h2"/><div className="tree t1"/><div className="tree t2"/><div className="child"/><div className="stars">✦　✧　✦</div></div>}
